    "text": "دیانت داري\\n\\nد ماشومانو د زده کړي نتيجی\\n\\nد دې سبق د وئیلو نه پس به ماشومان\\n\\nد خپلو قدرونو لکه جرګه ،مرکه میلمستیا او ښبگره و غیره\\n\\nد تقريرونو، مکالمو او مباحثو په اورېدو ئې د هغې سره دلچسپي پېدا شي. د رشتو پېژندلو نظر او ژبه یی نوره هم پراخه شي\\n\\nپه بیان کښي د خپلو جذباتو څرګندونه کولی شي.\\n\\nفاعل فعل او مفعول وپېژني\\n\\nخاص لفظونه\\n\\n،ماسخوتن را چاپیره غوښتنو مشغولولو ،عبرت ،انکار ،خفگان، لونی تیته کښېښودو نورشالي کاکا چې د ماسخوتن د مونځ نه کور ته راشي نو د هغۀ د کور ټول ماشومان د هغۀ نه را چاپېره شي او غواړي چې د نورشالي کاکا نه خوږه قیصی واوري . هغه هم د ماشومانو په غوښتنو خوشحاليږي او چې ټول نمسي نمسۍ ئې موجود وي او چا ته چې د سکول کار نه وي پاتې نو نورشالي کاکاد دوي د مشغولولو او عبرت حاصلولو د پاره دوي ته قیصی کوي.\\n\\nنن چې څنګه نور شالی کاکا د مانځه نه راغلو او خپل کټ ته وختو نو ټولو ماشومانو ورته ووې چې بابا نن به راته خامخا قیصی کوئ . نورشالي كاكا مُسکے شو او وې وئيل چې بچو! ما خو کله هم انکار نۀ دے کرے ۔ ښه په ارام او ښه په غور دا قیصی واورئ خو داسې به کوئ چې د دې قیصۍ د کردار مامونی خوی او عادت به تاسو هم په ځانونو کښې پېدا\\n\\nکوئ نو ټولو ورسره لوظ و کړو چې خامخا به ستاسو په خبرو عمل \"كوو نورشالي کاکا قیصه شروع کړه چې دا د ډېر وخت خبره ده چې زۀ سحر وختي د پيو شودو) اخستو د پاره د کلي دكان ته لاړم - ما شوده واخستل او څه نوره سودا مې کوله چې یوه ماشومه راغله ، پۍ ئې اخستل . د پيو لوښي ئې کښېښودو او دکاندار پکښې پی اچول چې هغه ناڅاپي په ژړا شوه او منډه ئې کړه په زمکه ئې څه لتون كولو او یو خوا بل خوا اوتره اوتره ګرځېده او په ژړا وه ـ زۀ ورمخکښې شوم او ورته مې ووې چې بچی دا ولې؟ څه وشو؟ هغې راته ووې چې ما نه پېسې چرته پرېوتې او اوس به دکاندار له څه ورکوم او کور به مور پلار ته څه وایم؟\\n\\nزما د هغې ماشومې په ژړا او خفګان",
