    "text": "ماحول یا چاپېر چل ټول هغه څه دي چې زمونږ نه یو خوا بل خوا لیدی او محسوسېدے شي . دغه یو خوا بل خوا او چار چاپېره څیزونه ژوندي دي او که بې ساه دي دغه زمونږ چاپېر چل دی او په خپله مونږ انسانان هم د دغه چاپېرچل برخه یو -\\n\\nدغه چاپېرچل په څو برخو کښې تقسیم دے لکه غریئز چاپېرچل مېداني چاپېر چل په غرئيز ماحول کښې غرونه ، چينې، ونې ، بوټي، خوړونه لوړه ژوره او په ځنې غرونو واوره پرته وي ځینې غرونه خشک\\n\\nخشک او اوچ کړس وي او ونې بوټي نه لري . په اباد و غرونو کښې ابادي\\n\\nډېره او په اوچو غرونو کښې ابادي كمه وي.\\n\\nمېداني چاپېر چل زیاته هواره زمکه لري او په دغه مېداني چاپېر چل کښې په زياته اندازه کرکیله کولی شي د اوبه خور زیات کار د نهرونو او ولو په ذریعه کولی شي ځينې ځايونو کښې ټيوب وېلونه او ارټونه هم زمکې خړوبوي - په مېداني ماحول کښې لوی لوی ښارونه او لوی لوی کلي وي او ابادي ئې زياته وي . دغه شان زياتې کارخانې د رېل پاټلۍ او پلن سړکونه هم په مېداني علاقو کښې وي .\\n\\nد چاپېرچل بل و پش یا تقسیم کلي وال چاپېر چل او ښاري چاپېر چل دے ۔ کلي وال چاپپرچل کښې خیچن والے کم وي . د خلقو استوګنه زیاته په کچه کورونو کښې وي يو خوا بل خوا شينکي او ونې بوټي وي خو خلق د صفایی ډېر خیال نه ساتي - د کورونو سره نزدې دېرانونه او د سخا اوبو ډنډونه وي - نالی زيات وخت بندې وي . د تګ راتګ ذريعې ئې څه ډېرې ښې نۀ وي - خلق ئې محنت کوونکي وي خو د صحت د اسانتیا کانونه لرلو په وجه اکثر خلق رنځوران وي .\\n\\nښاري ماحول کښې ادارې کار کوي - سړکونه پلن او لوی وي . آبادۍ یو بل سره جوختی او زیات کورونه تنګ او واړه وي ـ خلقو ته د تعلیم سهولتونه حاصل وي . د ژوند زیاتې اسانتياګانې موجودې وي. د صفایی د پاره خپل خلق مقرر وي - د تګ راتګ ښې وسیلې وي . د هسپتالونو او شفاخانو د موجودګۍ په وجه د رنځورانو علاج په ښه توګه کېدے شي - خلق ئي اكثر خوشحاله وي او د هر قسمه سهولتونو نه فائده اوچتولی شي.\\n\\nماحول پېژندنه ډېر اهم څیز دے او چې مونږ خپل چاپېرچل و پېژنو او د خپل چاپېر چل د ښه کولو د پاره هر قسم کوشش وکړو او په چاپېر چل کښې د انساني لاس وهنې مخنیوی وکړو نو زمونږ چاپېرچل به زمونږ د\\n\\nپاره سودمن وګرځي.\\n\\nښاري ماحول کښې ادارې کار کوي - سړکونه پلن او لوی وي . آبادۍ یو بل سره جوختی او زیات کورونه تنګ او واړه وي ـ خلقو ته د تعلیم سهولتونه حاصل وي . د ژوند زیاتې اسانتياګانې موجودې وي. د صفایی د پاره خپل خلق مقرر وي - د تګ راتګ ښې وسیلې وي . د هسپتالونو او شفاخانو د موجودګۍ په وجه د رنځورانو علاج په ښه توګه کېدے شي - خلق ئي اكثر خوشحاله وي او د هر قسمه سهولتونو نه فائده اوچتولی شي.\\n\\nماحول پېژندنه ډېر اهم څیز دے او چې مونږ خپل چاپېرچل و پېژنو او د خپل چاپېر چل د ښه کولو د پاره هر قسم کوشش وکړو او په چاپېر چل کښې د انساني لاس وهنې مخنیوی وکړو نو زمونږ چاپېرچل به زمونږ د\\n\\nپاره سودمن وګرځي.",
    "urdu": "اس سبق 'ماحول کی پہچان' میں طلبہ پشتو ادب، زبان دانی اور عمدہ اخلاقی اقدار سیکھتے ہیں۔ سبق میں لفظ بہ لفظ پشتو عبارت، سلیس اردو ترجمہ اور جامع مشقیں شامل ہیں۔",
