    "text": "د ماشومانو د زده کړې نتيجې\\n\\nایثار قرباني)\\n\\nد دې سبق د وئیلو نه پس به ماشومان\\n\\nد حالاتو مطابق د خپلو قدرونو په رڼا کښې د تعلق جوړولو چل زده کړی شي. گراني جملي په روانی وئيلي شي\\n\\nد حفظ مراتب مطابق سوال جواب کولے شي نيمګړې جملې پوره کولی شي\\n\\nخاص لفظونه\\n\\n،پیرید ،ایثار ،مطلب ،لفظي مثال ،الفاظ ،هفته ،عجیبه تنگسیا، مرسته\\n\\nنن چې د پښتو پېريد شروع شو او مس شائیسته کلاس ته راغله نو ماشومانو ته ئې ووئيل چې پرون عائیشه د ایثار د معنې پوښتنه کړې وه او ما لوظ کړی وۀ چې نن وخت کم دے، سبا به ئې درته بیان کړم - نن درته زه د ایثار معنی او\\n\\nمطلب بيانوم د ایثار لفظي معنى قرباني ورکول د خپل ضرورت لرلو با وجود د بل ضرورت پوره کول خان وروستو ،کول خپله ګټه پرېښودل او د بل فائده او ګټه وړاندې کول، دا ټول داسې الفاظ دي چې ورباندې پوهېدل لږ شان ګران دي. زه تاسو ته یوه واقعه بيانوم چې تاسو د ایثار په مطلب په پوره ډول پوهه شئ. وائي چې يو ځل د شام په ملک کښې د رومیانو سره د مسلمانانو غزا وه په جنگ کښې حضرت سلمه وي نو نومې يو صحابي زخمي شو را پر ہوتو\\n\\nماشومانو کله چې څوک زخمي شي نو تنده ورته زياته لكي - حضرت سلمه لال له او نه هم تر شو ځکه ئې په اوچت او از اوبه وغوښتلې - يو صحابي حضرت حذيفه الا الله و و ور له د اوبو ډک جام را وزغلوه - حضرت سلمه ده چې په جام خلۀ کېښودله نو خوا کښې ئې يو بل زخمي صحابي په زوره ووئیل اے مسلمانانو وروڼو ا لري او به راکړی چې مرۍ مې لونده شي - حضرت سلمه في اول صحابي ته ووئيل چې هغه سړی زما نه زیات توی ښکاري، زه به صبر وکړم ته د اوبو جام دغه کس له ورسوه حضرت حذيفه الا الله لا يا جام هغه بل زخمي له ورسولو نو د لرې نه چا چغه کړه چې د خدای د پاره یو ګوټ او به راکړی هغه دويم زخمي صحابي حضرت حذیفه ته ووئیل چې وروره دا اوبۀ هغه بل\\n\\nزخمي صحابي له يوسه ځکه چې هغۀ ته زما نه زيات د اوبو ضرورت دے۔ ماشومانو حضرت حذیفه ی چې دریم زخمي صحابي له څو رسېدو نوهغه بيا شهید شوی ؤ هغه ترې نه په دې نيت په تلوار را واپس شو چې وړومینو دوو\\n\\nصحابیانو ته اوبه اورسوي ولې څه ګوري چې هغوي دواړو هم ساه ورکړې وه او د شهادت په مرتبه رسېدلي وو . دغه شان د اوبو جام ډک په ډکه د حضرت",
