    "text": "د ماشومانو\\n\\nاخترونه\\n\\nد دې سبق د وئیلو نه پس به ماشومان\\n\\nپه سماجي توګه وده ومومي او ناسته پاسته به ئې د خپل دود دستور سره سمه شي\\n\\nد خبرې اورېدو سره د هغي په ښه او بد د پوهېد و جوګه شي.\\n\\nپه خپله و بنا کښې د قدرې ګرانو لفظونو د استعمالولو جوګه شي. په لوست کښې د بې ترتيبه جملو ادراک وکړی شي.\\n\\nخاص لفظونه\\n\\nنمانځي، عيد الفطر، نارینه عیدگاه فطرانه سرسایه ذي الحجه حلالوي وګڼله رضا\\n\\nمسلمانان په کال کښې د خوشحالۍ دوه ورځې نمانځي . په دغو کښې یو ته وړوکی اختر یا عید الفطر او دویم ته لوی اختر یا د قربانۍ اختر وئیلی شي وړوکی اختر د روژې نه پس وي . په دغه ورځ هر څوک نوې او پاکې جامې اغوندي او نارینه د اختر مونځ د پاره عیدګاه ته لاړ شي ـ د اختر د مانځه نه اګاهو شته من خلق په یوه خاصه اندازه پېسې با غله غريبانانو له ورکوي . دغه سرسایه یا فطرانه بللی شي. د دې غرض دا وي چې زمونږ غریبانان وروڼه خوېندې هم د اختر په خوشحالو کښې شريک شي.\\n\\nد اختر په ورځ خلق يو بل له د اختر مبارکي ورکوي خپلو خپلوانو کره ځي راځي - رنگ رنگ خوراکونه تياروي په کلو او ښارونو کښې د اختر مېلې لګي چې هر څوک پکښې د خپلې خوښې څیزونه اخلي . دغه شان د وړوکي اختر په موقع مشران ماشومانو له د اختر پېسې ورکوي. د مسلمانانو دویمه د خوشحالۍ ورځ لوی اختر یا د قربانۍ اختر دے ۔ دا د اسلامي میاشتي ذى الحجه په لسمه ورځ نمانځل شي . په لوی اختر کښې خلق قرباني کوي او بیا د قربانۍ غوښه په خپله هم خوري او نورو خپلوانو او غریبانانو له ئې هم ورکوي.\\n\\nلوی اختر یا د قربانی اختر د حضرت ابراهیم علیه السلام او د هغه د زوي حضرت اسماعیل علیه السلام د قربانی یاد تازه کوي - حضرت ابراهیم علیه السلام په خوب کښې ولیدل چې هغه خپل زوی حضرت\\n\\nاسماعيل عليه السلام حلالوي . کله چې دا خوب پرله هغه څو ځله",
    "urdu": "اس سبق 'اسلامی تہوار و عیدین' میں طلبہ پشتو ادب، زبان دانی اور عمدہ اخلاقی اقدار سیکھتے ہیں۔ سبق میں لفظ بہ لفظ پشتو عبارت، سلیس اردو ترجمہ اور جامع مشقیں شامل ہیں۔",
