    "text": "رانه شخصیتونه\\n\\nد ماشومانو د زده کړي نتيجي\\n\\nد دې قیصۍ د وئیلو نه پس به ماشومان\\n\\nوړې قیصى لطيفې شعرونه واړه کتابونه او په ورځ پاڼو او مجلو کښې د ماشومانو\\n\\nپانی ولوستي شي\\n\\nلیکونه په داسې توجه ولولي چې ورته یاد پاتې شي.\\n\\nد ګرانو ټکو لوست او مفهوم زده کړي.\\n\\nخاص لفظونه\\n\\nاوسیدونکے پرانسته تیره سپېځلی مجاهد تحریک واکداران، خطری قطعی شخصیت زمونږ يو قامي مشر څوک چې دصوابۍ کوټې نومې کلي اوسېدونکی وۀ. د نوي تعليم د زده کړې د پاره په پېښور کښې د یو سکول پرانسته کول غوښتل - دغه وخت په پښتنو کښې د نوي تعليم په حواله عجیبه عجیبه خبرې خورې وې - قامي مشر غوښتل چې دغه سکول بنيادي تيږه د یو داسې کس په لاس کيږدي چې په اولس کښې ورته په درنه سترګه کتلی شي د دې سپېځلي کار د پاره دوي د یو لوی مجاهد، آزادي خوښ او عالم نوم غوره کړو او هغوي ته ئې بلنه ورکړه په هغه ورځو کښې د دغه لوی مجاهد آزادی تحریک کرم و او انگرېزانو د هغوي د نیولو وارنټ جاري کړے وۀ\\n\\nځکه د ه د ډېرو خلقو دا خيال وه چې هغوي به رانه شي - ملګريو هم دغه رون\\n\\nخصیت ته خبرداری ورکړے وۀ چې د حکومت واکداران به موجود\\n\\nپه دې وجه ستاسو تلل به د خطرې نه خالي نه وي . ولي هغوي جواب ورکړو",
