    "authorInfo": "د پښتو درسي کتاب، دریم ټولګی، لوست نمبر 27.",
    "text": "خاص لفظونه\\n\\nسيمې لوبغاړي هلكان جينکى کلي ډنډه پت پتونی چیندرو، میرګاني، ګوډياني، ضابطه لوبې د هر وطن او هرې سیمې د ماشومانو او زلمو د پاره يو شان مزه لري . لوبې په ډېر قسمه وي خو په دغه ټولو قسمونو کښې چستي، تېزي او حاضر دماغي يو لوبغاړي له کاميابي ورکوي ځينې لوبې د ماشومانو هلکانو د پاره وي اوځينې د وړو جينکو د پاره وي ځينې لوبې هلکان او جینکۍ\\n\\nه دواړه کوي او بیاځينې لوبې صرف ځوانان کولی شي د زلمو په لوبو کښې د وجود د طاقت او زور زیات ضرورت وي او تېزي هم لري خو د ماشومانو لوبې داسې وي چې د کور دننه هم کېدی شي - زمونږ د کلو په لارو کوڅو کښي اکثر ماشومان گلي ډنډه ، کبډي پټ پټونے اوځينې نورې لوبې کوي او جینکۍ ميركاتي چيندر و او پټ پټوني سره سره کورکي جوړوي او ګوډيانې لوبوي.\\n\\nپه لوبو کولو ماشومان او زلمي خوشحاليږي او ورسره ئې صحت هم روغ جوړ وي - لوبو کولو سره په یو لوبغاړي کښې ځينې ښۀ صفتونه هم پیدا شي . د مثال په توګه په یوه لوبه کښې لوبغاړي د يو مشر د حکم لاندې وي . د هغۀ حكم مني او پکښې د منلو او تابعدارۍ کولو جذبه پېدا شي.\\n\\nد هرې لوبې د پاره څۀ ضابطه او قانون وي او داسې په بنده کښې د ه\\n\\nقانون د پابندی او په قانون د عمل کولو عادت پېدا شي. په لوبو کښې ګټه او بائبلات دواړه وي او داسې لوبې په يو لوبغاړي کښې د حوصلې صفت پیدا کوي او پکښې د خوشحالۍ او خفګان د زغملو حوصله پیدا کړي . دغه شان لوبې د پابندی (ډسپلن حوصلې او زغم صفتونه پیدا کوي زمونږ د وطن پاکستان قامي لوبه ها کي ده خو زمونږ په وطن کښې کرکټ ډېر زيات خوښولی شي - هاكي او کرکټ د سړو نه علاوه ښځې هم کوي او اوس خو د کرکټ د ړندو لوبغاړو ټیم هم زمونږ د وطن د نوم روښانه کولو د پاره جوړ کړے شوے دے۔ زمونږ د وطن په نورو لوبو کښې والي بال او فټ بال هم په شوق سره کولی شي.\\n\\nلوبې يوه داسې ذریعه ده چې د دنیا ملکونه يو بل ته رانزدې کوي . د دې په ذریعه د یو ملک وګړي د بل ملک د خلقو سره پېژند ګلو پېدا کوي او دغه\\n\\nشان عزت او احترام مومي\\n\\nمشغولتيا\\n\\nد سوالونو لنډ جوابونه وليکئ: د جينکو لوبې کومې کومې دي ؟\\n\\nزلمو په لوبو کښې د څۀ زيات ضرورت دے؟\\n\\nلارو کوڅو کښې ماشومان کومې کومې لوبې کوي؟",
