    "text": "ROF\\n\\nELPING\\n\\nکوي . دغه اجتماعی خدمت دی ۔\\n\\nد اجتماعي خدمت ترسره کولو د پاره چې کومې ډلې او تنظيمونه جوړ کړی شي هغې ته ادارې وئیلی شي ادارې اولسي هم وي او سرکاري هم . په دغو ادارو کښې سکولونه ،کالجونه، یونیورستۍ، مدرسې، بینکونه هسپتالونه ،سکاوټ، گرلز گائیډ د ښار د دفاع تنظیمونه او رضا کار\\n\\nتنظيمونه شامل دي. دا ټولې ادارې د اولس او قام په څه نه څۀ طريقه خدمت\\n\\nكوي\\n\\nپه دې ادارو کښې ځينې تعليمي ادارې دي چې د هغوي کار د اولس\\n\\nماشومانو او زلمو ته زده کړه او تعليم وركول دي . لکه سکولونه ، کالجونه يونيورستۍ او مدرسې ځينې ادارې نور خدمتونه کوي لکه هسپتالونه د ناروغو او رنځورانو علاج کوي - بېنکونه د خلقو د پېسو حفاظت کوي او ضرورت مندوته قرض پېسې هم ورکوي - سکاوټ او گرلز گائیډ د خبر ښېګړې کارونه کوي او د ښاري دفاع تنظيم د جنګ په وخت د ښار د خلقو حفاظت د پاره د هغوي لارښودنه کوي . دغه شان نور رضا کار تنظیمونه د\\n\\nزلزلو ، سېلابونو او قدرتی افتونو په وخت د خلقو د ژغورلو او محفوظو ځايونو ته د رسولود پاره ګامونه پورته کوي.\\n\\nد دغو ټولو ادارو غرض او مقصد یو دی او هغه د خلقو خدمت کول دي ـ په کوم وطن کښې چې د خېر ښېګړې ادارې ډېرې وي ، نو د هغه وطن\\n\\nاولس ته ډېرې اسانتیا ګانې حاصلې وي او ژوند ئې د خوشحالو نه ډک وي.\\n\\nمشغولتيا",
    "urdu": "اس سبق 'سرکاری و سماجی ادارے' میں طلبہ پشتو ادب، زبان دانی اور عمدہ اخلاقی اقدار سیکھتے ہیں۔ سبق میں لفظ بہ لفظ پشتو عبارت، سلیس اردو ترجمہ اور جامع مشقیں شامل ہیں۔",
